import sys

def can_place_ones(n, k):
    # Calculate the maximum number of ones that can be placed symmetrically
    max_ones = n * (n + 1) // 2
    return k <= max_ones

def construct_symmetric_matrix(n, k):
    if not can_place_ones(n, k):
        return -1

    matrix = [[0] * n for _ in range(n)]
    count = 0

    # Fill the upper triangle including the diagonal
    for i in range(n):
        for j in range(i, n):
            if count < k:
                matrix[i][j] = 1
                matrix[j][i] = 1
                count += 2

    return matrix

def print_matrix(matrix):
    for row in matrix:
        print(' '.join(map(str, row)))

